#!/usr/bin/env python3
# Some portions generated by Codex. Read-only existing JFR event reduction.
import json,pathlib,datetime
p=pathlib.Path(__file__).resolve().parent
d=p.parent/'workbench-e2e'
out={}
for name in ['transport-profile-on','memo-entry-profile-on']:
 es=json.loads((p/(name+'-jit-events.json')).read_text())['recording']['events']
 manifest=json.loads((d/(name+'-manifest.json')).read_text())
 result={'recordedCompilations':0,'recordedMemoCompilations':0,'memoDeoptimizations':[],'recordedCompilationFailures':[]}
 for e in es:
  v=e['values'];kind=e['type']
  if kind=='jdk.Compilation':
   result['recordedCompilations']+=1
   if 'NativeValueMemo' in v.get('method',{}).get('type',{}).get('name',''): result['recordedMemoCompilations']+=1
  if kind=='jdk.Deoptimization' and 'NativeValueMemo' in json.dumps(e):
   result['memoDeoptimizations'].append({**{k:v[k] for k in ['compileId','compiler','lineNumber','bci','instruction','reason','action']},'secondsFromQueryStart':datetime.datetime.fromisoformat(v['startTime']).timestamp()-manifest['queryStartEpochMs']/1000})
  if kind=='jdk.CompilationFailure': result['recordedCompilationFailures'].append({k:v[k] for k in ['compileId','failureMessage']})
 out[name]=result
print(json.dumps(out,indent=2))
